public class ThreadStateDemo {
    public static void main(String[] args) throws InterruptedException {
        var lock = new Object();

        var thread = new Thread(() -> {
            synchronized (lock) {
                try {
                    lock.wait(); // Moves to WAITING
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        System.out.println("Before start: " + thread.getState()); // NEW
        thread.start();
        Thread.sleep(50); // Let thread acquire lock and wait
        System.out.println("After wait: " + thread.getState()); // WAITING

        synchronized (lock) {
            lock.notify(); // Wake up the waiting thread
        }
        thread.join();
        System.out.println("After finish: " + thread.getState()); // TERMINATED
    }
}
