public class OrderProcessor {
    public static void main(String[] args) throws InterruptedException {
        var orders = List.of("ORD-001", "ORD-002", "ORD-003");
        var workers = new ArrayList<Thread>();

        for (var orderId : orders) {
            var worker = new Thread(() -> {
                System.out.println("Processing " + orderId);
                try {
                    Thread.sleep(1000); // Simulate work
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                System.out.println("Completed " + orderId);
            });
            worker.start();
            workers.add(worker);
        }

        // Wait for all workers to finish before aggregating
        for (var worker : workers) {
            worker.join(); // Main thread waits here
        }

        System.out.println("All orders processed, generating report");
    }
}
