public class PriorityDemo {
    public static void main(String[] args) {
        var lowPriorityTask = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                System.out.println("Low priority: " + i);
            }
        });

        var highPriorityTask = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                System.out.println("High priority: " + i);
            }
        });

        // Set priorities before starting threads
        lowPriorityTask.setPriority(Thread.MIN_PRIORITY); // 1
        highPriorityTask.setPriority(Thread.MAX_PRIORITY); // 10

        System.out.println("Low priority: " + lowPriorityTask.getPriority());
        System.out.println("High priority: " + highPriorityTask.getPriority());

        lowPriorityTask.start();
        highPriorityTask.start();

        // Output order is NOT guaranteed despite priority difference
    }
}
